import { PremiumBadge, ProductFeatureDetails } from "@/components/PremiumFeaturePlaceholder"
import { premiumFeatureForNode } from "@/lib/premium-features"
import { isProductNodeAvailable } from "@/lib/product-features"
import { useMemo, useRef, useState } from "react"
import { PlusIcon } from "lucide-react"
import {
  Dialog,
  DialogContent,
  DialogHeader,
  DialogTitle,
} from "@/components/ui/dialog"
import { Input } from "@/components/ui/input"
import { Button } from "@/components/ui/button"
import { useLayoutMigration } from "@/components/layout/LayoutMigrationDialog"
import { Label } from "@/components/ui/label"
import { Tabs, TabsContent, TabsList, TabsTrigger } from "@/components/ui/tabs"
import {
  addLibrarySelection,
  getSavedNodes,
  canContainLayoutNode,
  isMovableLayoutNode,
  libraryItemsForParent,
  readNodes,
  readScenes,
  type LibraryItemDef,
  type LibraryParentContext,
} from "@/lib/nodes-admin"
import { useAdminMap } from "@/lib/live-map-options"
import { cn } from "@/lib/utils"
import { readLayoutOptions, slotIdFromName } from "@/lib/layout-grid"

type Props = {
  open: boolean
  onOpenChange: (open: boolean) => void
  context: LibraryParentContext | null
  existingSlotIds?: string[]
  onAdded?: (nodeId: string) => void
}

function LibraryCard({
  item,
  onPick,
}: {
  item: LibraryItemDef
  onPick: () => void
}) {
  const Icon = item.icon
  return (
    <button
      type="button"
      onClick={onPick}
      className={cn(
        "flex w-full items-start gap-3 rounded-lg border border-border bg-background p-3 text-left",
        "transition-colors hover:border-primary/40 hover:bg-muted/40",
      )}
    >
      <span className="flex size-9 shrink-0 items-center justify-center rounded-md bg-muted">
        <Icon className="size-4 text-muted-foreground" />
      </span>
      <span className="min-w-0">
        <span className="flex items-center gap-2 text-sm font-medium">{item.label}{!isProductNodeAvailable(item.type) ? <PremiumBadge /> : null}</span>
        <span className="block text-xs text-muted-foreground">
          {item.description}
        </span>
      </span>
    </button>
  )
}

/**
 * shadcn Dialog: add nodes from Library (new) or Saved (existing unattached).
 */
export function LibraryModal({
  open,
  onOpenChange,
  context,
  existingSlotIds = [],
  onAdded,
}: Props) {
  const map = useAdminMap()
  const { requestMigration } = useLayoutMigration()
  const nodes = readNodes(map)
  const scenes = readScenes(map)
  const saved = useMemo(
    () => getSavedNodes(nodes, scenes).filter(node => {
      if (context?.kind !== "node") return true
      const parent = nodes.find(item => item.id === context.nodeId)
      return parent ? canContainLayoutNode(parent, node, nodes) : false
    }),
    [nodes, scenes, context],
  )

  const libraryItems = useMemo(() => {
    if (!context) return []
    return libraryItemsForParent(context, nodes, scenes)
  }, [context, nodes, scenes])

  const [premiumType, setPremiumType] = useState<string | null>(null)
  const upgrading = useRef(false)
  const premiumFeature = premiumType ? premiumFeatureForNode(premiumType) : null
  const [slotDraft, setSlotDraft] = useState("")
  const [slotError, setSlotError] = useState<string | null>(null)
  const [pendingSlotPick, setPendingSlotPick] = useState(false)

  const close = () => {
    onOpenChange(false)
    setSlotDraft("")
    setSlotError(null)
    setPendingSlotPick(false)
    setPremiumType(null)
  }

  const finish = (nodeId: string) => {
    onAdded?.(nodeId)
    close()
  }

  const pickNew = (item: LibraryItemDef) => {
    if (!context || !map) return
    if (!isProductNodeAvailable(item.type)) { setPremiumType(item.type); return }
    if (context.kind === "page-grid" && item.type === "slot") {
      setPendingSlotPick(true)
      setSlotDraft("")
      setSlotError(null)
      return
    }
    const add = () => {
      const nodeId = addLibrarySelection(map, context, item.type)
      if (nodeId) finish(nodeId)
    }
    if (context.kind === "node" && isMovableLayoutNode({
      id: "", type: item.type, title: "", settings: {}, children: [],
    })) requestMigration(add)
    else add()
  }

  const pickSaved = (nodeId: string) => {
    if (!context || !map) return
    const savedNode = nodes.find((node) => node.id === nodeId)
    if (savedNode && !isProductNodeAvailable(savedNode.type)) { setPremiumType(savedNode.type); return }
    const add = () => {
      const id = addLibrarySelection(map, context, "view", { savedNodeId: nodeId })
      if (id) finish(id)
    }
    if (context.kind === "node" && savedNode && isMovableLayoutNode(savedNode)) {
      requestMigration(add)
    } else add()
  }

  const submitSlot = () => {
    if (!context || context.kind !== "page-grid" || !map) return
    const title = slotDraft.trim()
    if (!title) {
      setSlotError("Enter a name.")
      return
    }
    const ids = [...existingSlotIds, ...readNodes(map).map(node => node.id),
      ...Object.values(readLayoutOptions(map.options.layout).grids).flatMap(grid => grid.map(widget => widget.id))]
    const nodeId = addLibrarySelection(map, context, "slot", {
      slotId: slotIdFromName(title, ids), slotTitle: title,
    })
    if (nodeId) finish(nodeId)
  }

  return (
    <Dialog open={open} onOpenChange={(next) => (next ? onOpenChange(true) : close())}>
      <DialogContent className="sm:max-w-lg" onCloseAutoFocus={event => { if (upgrading.current) { upgrading.current = false; event.preventDefault() } }}>
        {!premiumFeature ? <DialogHeader>
          <DialogTitle>Add component</DialogTitle>
        </DialogHeader> : null}

        {premiumFeature ? <ProductFeatureDetails feature={premiumFeature} onBack={() => setPremiumType(null)} onUpgrade={() => { upgrading.current = true }} /> : pendingSlotPick ? (
          <div className="grid gap-3 py-2">
            <Label htmlFor="library-slot-id">Name</Label>
            <Input
              id="library-slot-id"
              value={slotDraft}
              placeholder="e.g. Left sidebar"
              autoFocus
              onChange={(e) => {
                setSlotDraft(e.target.value)
                setSlotError(null)
              }}
              onKeyDown={(e) => {
                if (e.key === "Enter") {
                  e.preventDefault()
                  submitSlot()
                }
              }}
            />
            {slotError ? (
              <p className="text-xs text-destructive">{slotError}</p>
            ) : null}
            <div className="flex justify-end gap-2">
              <Button
                type="button"
                variant="outline"
                onClick={() => setPendingSlotPick(false)}
              >
                Back
              </Button>
              <Button
                type="button"
                onClick={submitSlot}
              >
                <PlusIcon className="size-4" />
                Add slot
              </Button>
            </div>
          </div>
        ) : (
          <Tabs defaultValue="library" className="gap-3">
            <TabsList className="grid w-full grid-cols-2">
              <TabsTrigger value="library">Library</TabsTrigger>
              <TabsTrigger value="saved">Saved</TabsTrigger>
            </TabsList>

            <TabsContent value="library" className="mt-0 max-h-[50vh] space-y-2 overflow-y-auto">
              {libraryItems.length === 0 ? (
                <p className="py-6 text-center text-sm text-muted-foreground">
                  Nothing to add here.
                </p>
              ) : (
                libraryItems.map((item) => (
                  <LibraryCard
                    key={item.type}
                    item={item}
                    onPick={() => pickNew(item)}
                  />
                ))
              )}
            </TabsContent>

            <TabsContent value="saved" className="mt-0 max-h-[50vh] space-y-2 overflow-y-auto">
              {saved.length === 0 ? (
                <p className="py-6 text-center text-sm text-muted-foreground">
                  No saved components.
                </p>
              ) : (
                saved.map((node) => (
                  <button
                    key={node.id}
                    type="button"
                    onClick={() => pickSaved(node.id)}
                    className="flex w-full items-center justify-between rounded-lg border border-border px-3 py-2 text-left text-sm hover:bg-muted/40"
                  >
                    <span className="flex items-center gap-2 font-medium">{node.title || node.id}{!isProductNodeAvailable(node.type) ? <PremiumBadge /> : null}</span>
                    <span className="text-xs text-muted-foreground">{node.type}</span>
                  </button>
                ))
              )}
            </TabsContent>
          </Tabs>
        )}
      </DialogContent>
    </Dialog>
  )
}
