import { containerLayout, mergeContainerLayout, type ContainerLayout } from "../../../mapsvg/Layout/ResponsiveLayout"
import { classicLayoutGrids, LAYOUT_BREAKPOINTS, readLayoutOptions, type LayoutBreakpoint, type LayoutOptionsSlice } from "@/lib/layout-grid"
import { isMovableLayoutNode, readNodes, readScenes, type MapSvgNode } from "@/lib/nodes-admin"
import type { MapsvgMapInstance } from "@/lib/mapsvg-client"

export { containerLayout }
export type { ContainerLayout }
export function isContainerHidden(node: MapSvgNode, bp: LayoutBreakpoint, layout: LayoutOptionsSlice): boolean {
  return !!containerLayout(node, bp).hidden || (node.type === "slot" && !layout.grids[bp].some(widget => widget.id === node.id))
}

/** Restore an omitted slot without changing its identity/contents in other layouts. */
export function showContainer(layout: LayoutOptionsSlice, node: MapSvgNode, bp: LayoutBreakpoint): LayoutOptionsSlice {
  if (node.type !== "slot" || layout.grids[bp].some(widget => widget.id === node.id)) return layout
  const source = LAYOUT_BREAKPOINTS.flatMap(key => layout.grids[key]).find(widget => widget.id === node.id)
  const bottom = Math.max(0, ...layout.grids[bp].map(widget => widget.y + widget.h))
  return { ...layout, grids: { ...layout.grids, [bp]: [...layout.grids[bp], { id: node.id, x: 0, y: bottom, w: bp === "mobile" ? layout.column : Math.min(layout.column, source?.w ?? 4), h: source?.h ?? 2 }] } }
}

export function containerSettingsPatch(map: MapsvgMapInstance, nodeId: string, bp: LayoutBreakpoint, change: ContainerLayout) {
  const nodes = readNodes(map), layout = readLayoutOptions(map.options.layout)
  const node = nodes.find(item => item.id === nodeId)
  const nextNodes = nodes.map(item => item.id === nodeId ? { ...item, settings: { ...item.settings,
    responsiveLayout: { ...(item.settings.responsiveLayout as object ?? {}), [bp]: mergeContainerLayout(containerLayout(item, bp), change) },
  } } : item)
  return { nodes: nextNodes, layout: node && change.hidden === false ? showContainer(layout, node, bp) : layout }
}

export function copyContainerLayout(map: MapsvgMapInstance, from: LayoutBreakpoint | "reset", to: LayoutBreakpoint) {
  const nodes = readNodes(map), layout = readLayoutOptions(map.options.layout)
  const classic = classicLayoutGrids()[to]
  // Reset never resurrects a globally deleted container or drops a custom one.
  const grid = from === "reset"
    ? nodes.filter(node => node.type === "slot").map((node, index) => classic.find(widget => widget.id === node.id) ?? { id: node.id, x: 0, y: 12 + index * 2, w: layout.column, h: 2 })
    : structuredClone(layout.grids[from])
  return {
    layout: { ...layout, grids: { ...layout.grids, [to]: grid } },
    nodes: nodes.map(node => node.type === "slot" || isMovableLayoutNode(node) ? { ...node, settings: { ...node.settings,
      responsiveLayout: { ...(node.settings.responsiveLayout as object ?? {}), [to]: from === "reset" ? {} : containerLayout(node, from) },
    } } : node),
  }
}

/** Deletion is global and must never orphan content, a Page, or an action target. */
export function containerDeleteReason(map: MapsvgMapInstance, nodeId: string): string | null {
  const nodes = readNodes(map), node = nodes.find(item => item.id === nodeId)
  if (!node || !["slot", "frame"].includes(node.type)) return "This container cannot be deleted."
  return layoutNodeDeleteReason(map, nodeId)
}

/** Map internals have the same lifetime as Map; containers still require moving their content. */
export function layoutNodeDeletionIds(nodes: MapSvgNode[], nodeId: string): Set<string> {
  const ids=new Set<string>([nodeId])
  if(nodes.find(node=>node.id===nodeId)?.type!=="map")return ids
  const visit=(id:string)=>{
    for(const child of nodes.find(node=>node.id===id)?.children??[]) {
      if(ids.has(child))continue
      ids.add(child);visit(child)
    }
  }
  visit(nodeId)
  return ids
}

/** Shared guard for canvas and inspector deletion. */
export function layoutNodeDeleteReason(map: MapsvgMapInstance, nodeId: string): string | null {
  const nodes = readNodes(map), node = nodes.find(item => item.id === nodeId)
  if (!node || (node.type !== "slot" && !isMovableLayoutNode(node))) return "This component cannot be deleted."
  if (node.type !== "map" && node.children?.length) return "Move its components to another container before deleting it. You can hide it in this layout instead."
  if (readScenes(map).some(scene => scene.rootNodeId === nodeId || scene.bodyNodeId === nodeId)) return "This container is a Page root. Choose another root before deleting it."
  const removed=layoutNodeDeletionIds(nodes,nodeId)
  const mobileView = map.options.mobileView as Record<string, unknown> | undefined
  if (removed.has(String(mobileView?.mapContainerId)) || removed.has(String(mobileView?.listContainerId))) return "Mobile Toolbar targets this container. Change its target before deleting it."
  const actions = map.options.actions as Record<string, { click?: { showAnotherMapNodeId?: string } }> | undefined
  if (Object.values(actions ?? {}).some(group => removed.has(String(group?.click?.showAnotherMapNodeId)))) return "An interaction targets this container. Change that interaction before deleting it."
  return null
}

export function deleteContainerPatch(map: MapsvgMapInstance, nodeId: string) {
  if (containerDeleteReason(map, nodeId)) return null
  return deleteLayoutNodePatch(map, nodeId)
}

export function deleteLayoutNodePatch(map: MapsvgMapInstance, nodeId: string) {
  if (layoutNodeDeleteReason(map, nodeId)) return null
  const layout = readLayoutOptions(map.options.layout), nodes=readNodes(map)
  const removed=layoutNodeDeletionIds(nodes,nodeId)
  const node=nodes.find(node=>node.id===nodeId)!
  const remaining=nodes.filter(node=>!removed.has(node.id))
  const deletedNodeTypes=new Set(layout.deletedNodeTypes??[])
  if(["map","mobileToolbar"].includes(node.type)&&!remaining.some(item=>item.type===node.type))deletedNodeTypes.add(node.type)
  return { layout: { ...layout, ...(deletedNodeTypes.size?{deletedNodeTypes:[...deletedNodeTypes]}:{}), grids: Object.fromEntries(LAYOUT_BREAKPOINTS.map(bp => [bp, layout.grids[bp].filter(widget => !removed.has(widget.id))])) },
    nodes: remaining.map(node => ({ ...node, children: node.children?.filter(id => !removed.has(id)) })),
  }
}
