import { Button } from "@/components/ui/button"
import { Dialog, DialogContent, DialogDescription, DialogFooter, DialogHeader, DialogTitle } from "@/components/ui/dialog"
import { getAdminMapInstance } from "@/lib/apply-options-patch"
import { layoutNodeDeleteReason, deleteLayoutNodePatch } from "@/lib/layout-containers"
import { applyLayoutEdit } from "@/lib/layout-history"
import { readNodes } from "@/lib/nodes-admin"
import type { MapsvgMapInstance } from "@/lib/mapsvg-client"
import { useLayoutMigration } from "./LayoutMigrationDialog"

/** The inspector and canvas share the same guarded, undoable global deletion. */
export function DeleteLayoutNodeDialog({ map, nodeId, open, onOpenChange }: {
  map: MapsvgMapInstance | null; nodeId: string | null; open: boolean; onOpenChange: (open: boolean) => void
}) {
  const { requestMigration } = useLayoutMigration()
  if (!map || !nodeId) return null
  const node = readNodes(map).find(item => item.id === nodeId)
  const reason = layoutNodeDeleteReason(map, nodeId)
  const kind = node?.type === "slot" || node?.type === "frame" ? "container" : "component"
  return <Dialog open={open} onOpenChange={onOpenChange}>
    <DialogContent className="sm:max-w-md"><DialogHeader><DialogTitle>Delete {node?.title || nodeId}?</DialogTitle>
      <DialogDescription>{reason || `This removes the ${kind}${node?.type === "map" ? " and all its internal components" : ""} from Desktop, Tablet and Mobile. Database records are kept. You can undo this in Layout.`}</DialogDescription></DialogHeader>
      <DialogFooter><Button variant="outline" onClick={() => onOpenChange(false)}>Cancel</Button>
        <Button variant="destructive" disabled={!!reason} onClick={() => requestMigration(() => {
          if (getAdminMapInstance() !== map) return
          const patch = deleteLayoutNodePatch(map, nodeId)
          if (patch) {
            applyLayoutEdit({ ...patch, layout: { ...patch.layout, mountMode: "tree" } })
            onOpenChange(false)
          }
        })}>Delete from all layouts</Button></DialogFooter>
    </DialogContent>
  </Dialog>
}
