import { useSyncExternalStore } from "react"
import { toast } from "sonner"
import { getAdminMapInstance } from "@/lib/apply-options-patch"
import { patchLiveMapOptions } from "@/lib/live-map-options"
import { readNodes, readScenes } from "@/lib/nodes-admin"
import type { MapsvgMapInstance } from "@/lib/mapsvg-client"

const clone = <T,>(value: T): T => value === undefined ? value : structuredClone(value)
const equal = (a: unknown, b: unknown) => JSON.stringify(a) === JSON.stringify(b)
const object = (v: unknown): v is Record<string, unknown> => v !== null && typeof v === "object" && !Array.isArray(v)

/** Replay only the changed leaves. Never overwrite a later edit to the same leaf. */
export function replayLayoutChange(current: unknown, from: unknown, to: unknown): unknown {
  if (equal(from, to) || equal(current, to)) return clone(current)
  if (equal(current, from)) return clone(to)
  if (object(from) && object(to) && object(current)) {
    const result = clone(current)
    for (const key of new Set([...Object.keys(from), ...Object.keys(to)])) {
      if (equal(from[key], to[key])) continue
      const value = replayLayoutChange(current[key], from[key], to[key])
      if (value === undefined) delete result[key]
      else result[key] = value
    }
    return result
  }
  if (Array.isArray(from) && Array.isArray(to) && Array.isArray(current) &&
      [...from, ...to, ...current].every(value => object(value) && typeof value.id === "string")) {
    const result = clone(current) as Array<Record<string, unknown>>
    for (const id of new Set([...from, ...to].map(item => item.id))) {
      const a = from.find(item => item.id === id), b = to.find(item => item.id === id)
      if (equal(a, b)) continue
      const index = result.findIndex(item => item.id === id)
      const value = replayLayoutChange(result[index], a, b)
      if (value === undefined && index >= 0) result.splice(index, 1)
      else if (index >= 0) result[index] = value as Record<string, unknown>
      else result.push(value as Record<string, unknown>)
    }
    return result
  }
  throw new Error("This Layout value was changed outside Layout history.")
}

type Snapshot = Record<string, unknown>
type Entry = { before: Snapshot; after: Snapshot }
const snapshot = (map: MapsvgMapInstance): Snapshot => clone({ layout: map.options.layout, nodes: readNodes(map), scenes: readScenes(map), actions: map.options.actions, mobileView: map.options.mobileView })
// Runtime setLayout normalizes/mounts the nodes it sees synchronously. Install
// registry/reference changes first, then let the Layout setter reflow them once.
function writeLayoutPatch(patch: Record<string, unknown>): void {
  const { layout, ...rest } = patch
  patchLiveMapOptions({ ...rest, ...(layout === undefined ? {} : { layout }) })
}

const histories = new WeakMap<MapsvgMapInstance, { undo: Entry[]; redo: Entry[] }>()
let revision = 0
const listeners = new Set<() => void>()
const emit = () => { revision++; listeners.forEach(listener => listener()) }
const history = (map: MapsvgMapInstance) => {
  let result = histories.get(map)
  if (!result) { result = { undo: [], redo: [] }; histories.set(map, result) }
  return result
}

/** All Layout-owned writes (including container inspector) share this journal. */
export function applyLayoutEdit(patch: Record<string, unknown>): void {
  const map = getAdminMapInstance()
  if (!map) return
  const before = snapshot(map)
  writeLayoutPatch(patch)
  const after = snapshot(map)
  if (equal(before, after)) return
  const journal = history(map)
  journal.undo.push({ before, after })
  if (journal.undo.length > 50) journal.undo.shift()
  journal.redo = []
  emit()
}

export function replayLayoutHistory(direction: "undo" | "redo"): void {
  const map = getAdminMapInstance()
  if (!map) return
  const journal = history(map), entry = journal[direction][journal[direction].length - 1]
  if (!entry) return
  try {
    const patch = replayLayoutChange(snapshot(map), direction === "undo" ? entry.after : entry.before, direction === "undo" ? entry.before : entry.after) as Snapshot
    const current = snapshot(map)
    writeLayoutPatch(Object.fromEntries(Object.entries(patch).filter(([key, value]) => !equal(current[key], value))))
    journal[direction].pop()
    journal[direction === "undo" ? "redo" : "undo"].push(entry)
  } catch {
    journal.undo = []; journal.redo = []
    toast.info("Layout history was reset because the same settings changed elsewhere.")
  }
  emit()
}

export function useLayoutHistory(map: MapsvgMapInstance | null) {
  useSyncExternalStore(listener => { listeners.add(listener); return () => { listeners.delete(listener) } }, () => revision)
  return { canUndo: !!map && history(map).undo.length > 0, canRedo: !!map && history(map).redo.length > 0 }
}
