export const PREVIEW_VIEWPORTS = {
  desktop: { width: 1280, height: 768 },
  tablet: { width: 768, height: 1024 },
  mobile: { width: 380, height: 800 },
} as const
export const PREVIEW_APP_WIDTHS = [25, 50, 75, 100] as const
export type PreviewAppWidth = typeof PREVIEW_APP_WIDTHS[number] | 70
export type PreviewDevice = keyof typeof PREVIEW_VIEWPORTS
export type PreviewOrientation = "landscape" | "portrait"
export type PreviewProfile = "desktop" | `${Exclude<PreviewDevice, "desktop">}-${PreviewOrientation}`

export function defaultPreviewOrientation(device: PreviewDevice): PreviewOrientation {
  return device === "desktop" ? "landscape" : "portrait"
}

export function previewProfile(device: PreviewDevice, orientation = defaultPreviewOrientation(device)): PreviewProfile {
  return device === "desktop" ? "desktop" : `${device}-${orientation}`
}

export function previewViewport(device: PreviewDevice, orientation = defaultPreviewOrientation(device)) {
  const size = PREVIEW_VIEWPORTS[device]
  return device === "desktop" || orientation === defaultPreviewOrientation(device)
    ? size : { width: size.height, height: size.width }
}

/** Breakpoint from iframe viewport CSS width, independent of App width and canvas zoom. */
export function previewLayoutBreakpoint(width: number): PreviewDevice {
  return width < 768 ? "mobile" : width <= 1024 ? "tablet" : "desktop"
}

/** Settings target the same profile as the selected iframe, including rotated Mobile. */
export function previewSessionLayoutBreakpoint(session?: { previewDevice?: PreviewDevice; previewOrientations?: Partial<Record<"tablet" | "mobile", PreviewOrientation>> }): PreviewDevice {
  const device = session?.previewDevice ?? "desktop"
  const orientation = device === "desktop" ? "landscape" : session?.previewOrientations?.[device] ?? defaultPreviewOrientation(device)
  return previewLayoutBreakpoint(previewViewport(device, orientation).width)
}
export const MAX_CANVAS_SCALE = 1
export const CANVAS_ZOOM_LEVELS = [0.25, 0.5, 0.75, MAX_CANVAS_SCALE] as const
export type CanvasPoint = { x: number; y: number }
export type CanvasSize = { width: number; height: number }
export type CanvasBounds = CanvasSize & CanvasPoint
export type CanvasView = { zoom: "fit" | "fit-app" | number; tool: "hand" | "arrow"; pan: CanvasPoint; appWidth?: PreviewAppWidth; appWidths?: Partial<Record<PreviewProfile, PreviewAppWidth>> }
export const DEFAULT_CANVAS_VIEW: CanvasView = { zoom: "fit-app", tool: "arrow", pan: { x: 0, y: 0 } }

export function previewAppWidth(view: CanvasView, device: PreviewDevice, orientation = defaultPreviewOrientation(device)): PreviewAppWidth {
  if (device === "mobile") return 100
  const saved = view.appWidths?.[previewProfile(device, orientation)] ?? (device === "desktop" ? view.appWidth : undefined)
  if (saved !== undefined && (saved === 70 || PREVIEW_APP_WIDTHS.some(width => width === saved))) return saved
  return device === "desktop" ? 50 : orientation === "landscape" ? 70 : 100
}

export function fitCanvasScale(area: CanvasSize, viewport: CanvasSize): number {
  return Math.max(0.01, Math.min(MAX_CANVAS_SCALE, (area.width - 48) / viewport.width, (area.height - 48) / viewport.height))
}

/** App bounds are measured in child viewport CSS pixels, independently of outer zoom. */
export function fitAppCanvas(area: CanvasSize, viewport: CanvasSize, bounds: CanvasBounds) {
  // Content outside the iframe remains accessible through its own page scrolling.
  const x = Math.max(0, bounds.x), y = Math.max(0, bounds.y)
  const width = Math.min(viewport.width, bounds.x + bounds.width) - x
  const height = Math.min(viewport.height, bounds.y + bounds.height) - y
  if (width <= 0 || height <= 0) return { scale: fitCanvasScale(area, viewport), pan: { x: 0, y: 0 } }
  const scale = fitCanvasScale(area, { width, height })
  return { scale, pan: { x: (viewport.width / 2 - x - width / 2) * scale, y: (viewport.height / 2 - y - height / 2) * scale } }
}

/** Transform origin is the viewport center; retain the content point under the cursor. */
export function zoomCanvasAt(pan: CanvasPoint, anchor: CanvasPoint, from: number, to: number): CanvasPoint {
  return { x: anchor.x - (anchor.x - pan.x) * to / from, y: anchor.y - (anchor.y - pan.y) * to / from }
}

export function clampCanvasScale(scale: number): number { return Math.max(0.1, Math.min(MAX_CANVAS_SCALE, scale)) }
