export const CORE_NODE_TYPES = Object.freeze([
  "slot",
  "frame",
  "body",
  "map",
  "modal",
  "popover",
  "tooltip",
  "directory",
  "filters",
  "region",
  "marker",
  "layers",
  "legend",
  "controls",
  "mobileToolbar",
  "view",
  "core",
] as const)

export type CoreNodeType = (typeof CORE_NODE_TYPES)[number]
export type NodeType = CoreNodeType | (string & {})

export function isCoreNodeType(type: string): type is CoreNodeType {
  return (CORE_NODE_TYPES as readonly string[]).includes(type)
}

export type MapSvgNode = {
  id: string
  type: NodeType
  title: string
  settings: Record<string, unknown>
  styles?: Record<string, unknown>
  template?: string
  css?: string
  js?: Record<string, string>
  children?: string[]
  [key: string]: unknown
}

export type TreeDropPosition = "before" | "after" | "inside"

export type TreeMoveResult =
  | { ok: true; nodes: MapSvgNode[]; parentId: string }
  | { ok: false; reason: string }

export function isMapInternalNode(node: MapSvgNode): boolean {
  return isMapInternalType(node.type)
}

/** Map internals and page-grid slots have fixed ownership; content nodes may move. */
export function isMovableLayoutNode(node: MapSvgNode): boolean {
  return !isMapInternalNode(node) && !["slot", "body"].includes(node.type)
}

export function canContainLayoutNode(parent: MapSvgNode, child: MapSvgNode, nodes?: MapSvgNode[]): boolean {
  if (parent.type === "map" || (nodes && isMapOwnedPlacement(nodes, parent.id))) return false
  if (nodes && !canSeparateMapAndList(nodes, parent.id, child.id)) return false
  if (!isMovableLayoutNode(child)) return false
  if (parent.type === "body") return child.type === "modal"
  return parent.type === "slot" || parent.type === "frame"
}

/** Evaluate a proposed attachment without mutating the existing tree. */
export function canSeparateMapAndList(nodes: MapSvgNode[], parentId: string, childId: string): boolean {
  const before = new Set(mixedMapListSlots(nodes))
  const proposed = nodes.map(node => ({ ...node, children: (node.children ?? []).filter(id => id !== childId) }))
  proposed.find(node => node.id === parentId)?.children?.push(childId)
  return mixedMapListSlots(proposed).every(id => before.has(id))
}

