/** Containers that accept [+] children in Layers. Map is NOT included — add a Frame under Map first. */
const ADDABLE_PARENT_TYPES = new Set<NodeType>(["slot", "frame", "body"])

export function canAddChildren(type: NodeType): boolean {
  return ADDABLE_PARENT_TYPES.has(type)
}

/** @deprecated use canAddChildren */
export function isFrameNodeType(type: NodeType): boolean {
  return canAddChildren(type) || type === "map"
}

function slug(input: string): string {
  return String(input || "")
    .trim()
    .replace(/\s+/g, "-")
    .replace(/[^a-zA-Z0-9_-]/g, "")
}

function uniqueId(base: string, used: Set<string>): string {
  const normalized = slug(base) || "node"
  if (!used.has(normalized)) {
    used.add(normalized)
    return normalized
  }
  let i = 2
  while (used.has(`${normalized}-${i}`)) i += 1
  const id = `${normalized}-${i}`
  used.add(id)
  return id
}

function toArray<T>(value: unknown): T[] {
  if (Array.isArray(value)) return value as T[]
  return []
}

export function readNodes(map: MapsvgMapInstance | null): MapSvgNode[] {
  return toArray<MapSvgNode>(map?.options?.nodes)
}

export function readScenes(map: MapsvgMapInstance | null): SceneNode[] {
  const scenes = toArray<SceneNode>(map?.options?.scenes).filter(
    (scene) => scene.id && scene.id !== "scene-modal",
  )
  if (scenes.length > 0) {
    return scenes.map((scene) => ({
      ...scene,
      bodyNodeId: scene.bodyNodeId || "body",
      title: scene.title || scene.id,
    }))
  }
  return [
    {
      id: "scene-1",
      title: "Scene 1",
      rootNodeId: "Main",
      bodyNodeId: "body",
      mount: { type: "dynamic" },
    },
  ]
}

export function nodeById(nodes: MapSvgNode[], id: string): MapSvgNode | undefined {
  return nodes.find((node) => node.id === id)
}

export function sceneById(scenes: SceneNode[], id: string): SceneNode | undefined {
  return scenes.find((scene) => scene.id === id)
}

export function sceneQueryId(scene: SceneNode, role: "objects" | "regions"): string {
  const saved = scene.dataBindings?.[role]
  if (
    saved &&
    typeof saved === "object" &&
    "queryId" in saved &&
    typeof saved.queryId === "string"
  ) {
    return saved.queryId
  }
  return role === "objects" ? "getObjects" : "getRegions"
}

export function patchSceneQueryBinding(
  scenes: SceneNode[],
  sceneId: string,
  role: "objects" | "regions",
  patch: Partial<SceneQueryBinding>,
): SceneNode[] {
  return scenes.map((scene) => {
    if (scene.id !== sceneId) return scene
    return {
      ...scene,
      dataBindings: {
        ...(scene.dataBindings ?? {}),
        [role]: {
          ...((scene.dataBindings?.[role] as SceneQueryBinding | undefined) ?? {}),
          ...patch,
        },
      },
    }
  })
}

export function updateSceneQueryBinding(
  scenes: SceneNode[],
  sceneId: string,
  role: "objects" | "regions",
  queryId: string,
): SceneNode[] {
  return patchSceneQueryBinding(scenes, sceneId, role, { queryId })
}

export function buildParentIndex(nodes: MapSvgNode[]): Map<string, string> {
  const parentById = new Map<string, string>()
  for (const node of nodes) {
    for (const childId of node.children ?? []) {
      parentById.set(childId, node.id)
    }
  }
  return parentById
}

export function findContainingSlotId(nodes: MapSvgNode[], nodeId: string): string | undefined {
  const byId = new Map(nodes.map((node) => [node.id, node]))
  const parents = buildParentIndex(nodes)
  const visited = new Set<string>()
  let parentId = parents.get(nodeId)
  while (parentId && !visited.has(parentId)) {
    visited.add(parentId)
    const parent = byId.get(parentId)
    if (parent?.type === "slot") return parent.id
    parentId = parents.get(parentId)
  }
  return undefined
}

export function getReachableIds(nodes: MapSvgNode[], rootIds: string[]): Set<string> {
  const byId = new Map(nodes.map((node) => [node.id, node]))
  const reachable = new Set<string>()
  const queue = [...rootIds]
  while (queue.length > 0) {
    const id = queue.shift()
    if (!id || reachable.has(id)) continue
    const node = byId.get(id)
    if (!node) continue
    reachable.add(id)
    for (const childId of node.children ?? []) {
      if (!reachable.has(childId)) queue.push(childId)
    }
  }
  return reachable
}

export function getSavedNodes(
  nodes: MapSvgNode[],
  scenes: SceneNode[],
  extraRootIds: string[] = [],
): MapSvgNode[] {
  const roots = [
    ...scenes.flatMap((scene) => [scene.rootNodeId, scene.bodyNodeId]),
    ...nodes.filter((node) => node.type === "slot").map((node) => node.id),
    ...extraRootIds,
  ].filter(Boolean)
  const reachable = getReachableIds(nodes, roots)
  return nodes.filter((node) => !reachable.has(node.id))
}

export function getSlotIdsFromLayout(
  map: MapsvgMapInstance | null,
  breakpoint: LayoutBreakpoint,
): string[] {
  const layout = map?.options?.layout
  if (!layout || typeof layout !== "object") return ["Main"]
  const grids = (layout as { grids?: Record<string, LayoutGsWidget[]> }).grids
  const order = [breakpoint, ...(["desktop", "tablet", "mobile"] as const).filter((bp) => bp !== breakpoint)]
  const ids = [...new Set(order.flatMap((bp) => (grids?.[bp] ?? []).map((w) => w.id).filter(Boolean)))]
  return ids.length > 0 ? ids : ["Main"]
}

export function legacyComponentIdForNode(node: MapSvgNode): string | null {
  switch (node.type) {
    case "map":
      return "map"
    case "modal":
      return "detailsView"
    case "popover":
      return "popover"
    case "tooltip":
      return "tooltip"
    case "directory":
      return "directory"
    case "filters":
      return "filters"
    case "region":
      return "region"
    case "marker":
      return "marker"
    case "layers":
      return "layers"
    case "legend":
      return "legend"
    case "controls":
      return "controls"
    case "mobileToolbar":
      return "mobileToolbar"
    case "slot":
    case "frame":
      return "layout"
    case "body":
      return null
    case "view":
      return null
    case "core":
      return "core"
    default:
      return null
  }
}

export function interactionGroupForNodeType(type: NodeType): string | null {
  switch (type) {
    case "region":
      return "region"
    case "marker":
      return "marker"
    case "directory":
      return "directory"
    case "map":
      return "map"
    default:
      return null
  }
}

export function libraryItemsForParent(
  context: LibraryParentContext,
  nodes: MapSvgNode[],
  scenes: SceneNode[] = [],
): LibraryItemDef[] {
  if (context.kind === "page-grid") {
    return LIBRARY_ITEMS.filter((item) => item.type === "slot")
  }

  const parent = nodeById(nodes, context.nodeId)
  if (!parent || isMapOwnedPlacement(nodes, parent.id)) return []
  const hasMobileToolbar = nodes.some((node) => node.type === "mobileToolbar")
  const slotId = slotForNode(nodes, parent.id)
  const allowed = (type: string) => (!["legend", "layers"].includes(type) || !nodes.some(node => node.type === type)) && (type !== "map" || canAddMapToPage(nodes, scenes, parent.id)) && (!slotId ||
    (type !== "directory" || !slotContainsType(nodes, slotId, "map", false)) &&
    (type !== "map" || !slotContainsType(nodes, slotId, "directory", false)))

  switch (parent.type) {
    case "slot":
      return LIBRARY_ITEMS.filter((item) => {
        if (!allowed(item.type)) return false
        if (item.type === "mobileToolbar") return !hasMobileToolbar
        return ["map", "directory", "filters", "view", "modal", "frame", "legend", "layers"].includes(item.type)
      })
    case "frame": {
      const childTypes = new Set(
        (parent.children ?? []).map((id) => nodeById(nodes, id)?.type).filter(Boolean),
      )
      return LIBRARY_ITEMS.filter((item) => {
        if (!allowed(item.type)) return false
        if (["layers", "legend"].includes(item.type)) {
          return !childTypes.has(item.type)
        }
        return ["directory", "filters", "view", "modal", "frame"].includes(item.type)
      })
    }
    case "body":
      return LIBRARY_ITEMS.filter((item) => item.type === "modal")
    default:
      return []
  }
}

function defaultTitle(type: NodeType | "slot"): string {
  if (type === "slot") return "Slot"
  if (type === "mobileToolbar") return "Mobile Toolbar"
  return type.charAt(0).toUpperCase() + type.slice(1)
}

function seedMapChildren(mapNodeId: string, used: Set<string>): MapSvgNode[] {
  const required: Array<{ suffix: string; type: NodeType; title: string }> = [
    { suffix: "region", type: "region", title: "Region" },
    { suffix: "marker", type: "marker", title: "Marker" },
    { suffix: "tooltip", type: "tooltip", title: "Tooltip" },
    { suffix: "popover", type: "popover", title: "Popover" },
    { suffix: "controls", type: "controls", title: "Controls" },
  ]
  return required.map(({ suffix, type, title }) => ({
    id: uniqueId(`${mapNodeId}-${suffix}`, used),
    type,
    title,
    settings: {},
    children: [],
  }))
}

export function createNodeDraft(
  type: NodeType | "slot",
  nodes: MapSvgNode[],
  title?: string,
): { nodes: MapSvgNode[]; nodeId: string } {
  const used = new Set(nodes.map((node) => node.id))
  const nodeType: NodeType = type === "slot" ? "slot" : type
  const id = uniqueId(title ?? defaultTitle(type), used)
  const next = [...nodes]
  const node: MapSvgNode = {
    id,
    type: nodeType,
    title: title ?? defaultTitle(type),
    settings: ["legend", "layers"].includes(nodeType) ? { on: true } : {},
    children: [],
  }
  next.push(node)

  if (nodeType === "map") {
    const seeded = seedMapChildren(id, used)
    node.children = seeded.map((child) => child.id)
    next.push(...seeded)
  }

  return { nodes: next, nodeId: id }
}

export function attachChild(nodes: MapSvgNode[], parentId: string, childId: string): MapSvgNode[] {
  return nodes.map((node) => {
    if (node.id !== parentId) return node
    const children = [...(node.children ?? [])]
    if (!children.includes(childId)) children.push(childId)
    return { ...node, children }
  })
}

export function detachChild(nodes: MapSvgNode[], parentId: string, childId: string): MapSvgNode[] {
  return nodes.map((node) => {
    if (node.id !== parentId) return node
    return {
      ...node,
      children: (node.children ?? []).filter((id) => id !== childId),
    }
  })
}

/**
 * Move a component in the flat nodes registry. Parent children are authoritative
 * for tree order; settings.placement is the component's persisted location.
 */
export function moveLayoutNode(
  nodes: MapSvgNode[],
  nodeId: string,
  targetId: string,
  position: TreeDropPosition,
  scenes: SceneNode[] = [],
): TreeMoveResult {
  const byId = new Map(nodes.map((node) => [node.id, node]))
  const moving = byId.get(nodeId)
  const target = byId.get(targetId)
  if (!moving || !target || !isMovableLayoutNode(moving)) {
    return { ok: false, reason: "This component cannot be moved." }
  }
  if (nodeId === targetId) return { ok: false, reason: "A component cannot contain itself." }

  const parents = buildParentIndex(nodes)
  const parentId = position === "inside" ? targetId : parents.get(targetId)
  const parent = parentId ? byId.get(parentId) : undefined
  if (parent && !canSeparateMapAndList(nodes, parent.id, moving.id)) {
    return { ok: false, reason: "Map and Directory must be in separate layout containers." }
  }
  if (!parent || !canContainLayoutNode(parent, moving, nodes)) {
    return { ok: false, reason: "This container cannot hold the component." }
  }
  if (getReachableIds(nodes, [nodeId]).has(parent.id)) {
    return { ok: false, reason: "A component cannot be moved into its descendant." }
  }

  const next = nodes.map((node) => ({
    ...node,
    children: [...(node.children ?? [])].filter((id) => id !== nodeId),
    settings: { ...node.settings },
  }))
  const nextParent = next.find((node) => node.id === parent.id)!
  const insertAt = position === "inside"
    ? nextParent.children!.length
    : Math.max(0, nextParent.children!.indexOf(targetId) + (position === "after" ? 1 : 0))
  nextParent.children!.splice(insertAt, 0, nodeId)
  const moved = next.find((node) => node.id === nodeId)!
  moved.settings.placement = { parentId: parent.id }

  const beforeConflicts = new Set(mixedMapListSlots(nodes))
  if (mixedMapListSlots(next).some(id => !beforeConflicts.has(id))) {
    return { ok: false, reason: "Map and Directory must be in separate layout containers." }
  }
  if (introducesExtraPageMap({ nodes, scenes }, { nodes: next, scenes })) {
    return { ok: false, reason: "Only one Map component can be added to a Page." }
  }
  return { ok: true, nodes: recordLayoutPlacements(next), parentId: parent.id }
}

/** Record each tree parent in component settings, preserving untouched external mounts. */
export function recordLayoutPlacements(nodes: MapSvgNode[]): MapSvgNode[] {
  const parents = buildParentIndex(nodes)
  return nodes.map((node) => {
    const parentId = parents.get(node.id)
    if (!isMovableLayoutNode(node) || !parentId) return node
    if (
      node.settings.location === "custom" &&
      typeof node.settings.containerId === "string" &&
      node.settings.containerId !== "" &&
      !node.settings.placement
    ) return node
    return { ...node, settings: { ...node.settings, placement: { parentId } } }
  })
}

/** Rename one logical page slot across the node registry and scene references. */
export function renameLayoutSlot(
  nodes: MapSvgNode[],
  scenes: SceneNode[],
  oldId: string,
  newId: string,
  title?: string,
): { nodes: MapSvgNode[]; scenes: SceneNode[] } | null {
  const oldSlot = nodes.find((node) => node.id === oldId && node.type === "slot")
  if (!oldSlot || nodes.some((node) => node.id === newId && node !== oldSlot)) return null
  return {
    nodes: nodes.map((node) => {
      const placement = node.settings?.placement
      const parentId = placement && typeof placement === "object"
        ? (placement as { parentId?: unknown }).parentId
        : undefined
      return {
        ...node,
        id: node.id === oldId ? newId : node.id,
        title: node.id === oldId ? title ?? (node.title === oldId ? newId : node.title) : node.title,
        children: (node.children ?? []).map((id) => id === oldId ? newId : id),
        settings: parentId === oldId
          ? { ...node.settings, placement: { ...(placement as object), parentId: newId } }
          : { ...node.settings },
      }
    }),
    scenes: scenes.map((scene) => ({
      ...scene,
      rootNodeId: scene.rootNodeId === oldId ? newId : scene.rootNodeId,
      bodyNodeId: scene.bodyNodeId === oldId ? newId : scene.bodyNodeId,
    })),
  }
}

export function writeNodesAndScenes(nodes: MapSvgNode[], scenes: SceneNode[]): void {
  patchLiveMapOptions({ nodes, scenes })
}

export function addLibrarySelection(
  map: MapsvgMapInstance | null,
  context: LibraryParentContext,
  itemType: NodeType | "slot",
  opts?: { slotId?: string; slotTitle?: string; savedNodeId?: string },
): string | null {
  let nodes = readNodes(map)
  let scenes = readScenes(map)
  if (context.kind === "node" && isMapOwnedPlacement(nodes, context.nodeId)) return null
  const before = { nodes, scenes }
  let nodeId = opts?.savedNodeId ?? null

  if (nodeId) {
    if (!nodeById(nodes, nodeId)) return null
  } else if (context.kind === "page-grid" && itemType === "slot") {
    const slotId = opts?.slotId?.trim()
    if (!slotId) return null
    if (nodeById(nodes, slotId)) return slotId
    nodes.push({
      id: slotId,
      type: "slot",
      title: opts?.slotTitle ?? slotId,
      settings: {},
      children: [],
    })
    nodeId = slotId
  } else {
    const created = createNodeDraft(itemType, nodes)
    nodes = created.nodes
    nodeId = created.nodeId
  }

  if (!nodeId) return null

  if (context.kind === "node") {
    if (!canSeparateMapAndList(nodes, context.nodeId, nodeId)) return null
    nodes = attachChild(nodes, context.nodeId, nodeId)
    if (introducesExtraPageMap(before, { nodes, scenes })) return null
    const attached = nodeById(nodes, nodeId)
    if (attached && isMovableLayoutNode(attached)) {
      nodes = nodes.map((node) => node.id === nodeId
        ? { ...node, settings: { ...node.settings, placement: { parentId: context.nodeId } } }
        : node)
      patchLiveMapOptions({
        nodes: recordLayoutPlacements(nodes),
        scenes,
        layout: { ...readLayoutOptions(map?.options.layout), mountMode: "tree" },
      })
      return nodeId
    }
  }

  writeNodesAndScenes(nodes, scenes)
  return nodeId
}
